<?php $dateValue=fn($v)=>$v?date('Y-m-d\TH:i',strtotime((string)$v)):''; ?>
<form method="post" class="content-edit" data-unsaved><?= csrf_field() ?><input type="hidden" name="version" value="<?= (int)$row['version'] ?>"><div class="admin-page-heading"><div><a class="text-link" href="/admin/content?type=<?= e($type) ?>">← กลับรายการ</a><h1><?= e($title) ?></h1></div><div class="button-row"><button class="button secondary" name="action" value="draft">บันทึกร่าง</button><?php if($old): ?><a class="button secondary" href="/admin/preview/<?= $old['id'] ?>" target="_blank" rel="noopener">ดูตัวอย่างที่บันทึก</a><?php endif ?><button class="button" name="action" value="save">บันทึกตามสถานะ</button></div></div><?php if($formError): ?><div class="alert error" role="alert"><?= e($formError) ?></div><?php endif ?><div class="editor-grid"><div><section class="admin-panel form-panel"><h2>ข้อมูล<?= e(CONTENT_TYPES[$type]) ?></h2><label>ชื่อเรื่อง <span class="required">*</span><input name="title" value="<?= e($row['title']) ?>" maxlength="250" required></label><?php if($type==='post'): ?><label>รูปแบบข่าว<select name="post_mode" data-post-mode><option value="article" <?= empty($row['external_url'])?'selected':'' ?>>ข่าวพร้อมเนื้อหา</option><option value="link" <?= !empty($row['external_url'])?'selected':'' ?>>ลิงก์ไปเว็บไซต์อื่น</option></select></label><div data-post-link><label>ลิงก์เว็บไซต์ปลายทาง<input type="url" name="external_url" value="<?= e($row['external_url']) ?>" placeholder="https://..."></label><p class="form-note">ข่าวแบบลิงก์ใส่เพียงชื่อข่าวและลิงก์ ไม่ต้องกรอกเนื้อหา หมวดหมู่ หรือรูปปก</p></div><?php endif ?><label>คำโปรย<textarea name="excerpt" rows="3" maxlength="1000"><?= e($row['excerpt']) ?></textarea></label><div class="field-group"><label for="body-editor">เนื้อหา</label><div class="editor-toolbar" role="group" aria-label="เครื่องมือจัดรูปแบบ"><button type="button" data-format="heading">หัวข้อ</button><button type="button" data-format="bold"><strong>B</strong></button><button type="button" data-format="italic"><em>I</em></button><button type="button" data-format="list">รายการ</button><button type="button" data-format="link">ลิงก์</button></div><textarea id="body-editor" name="body" rows="15" class="body-editor" placeholder="เขียนเนื้อหา แยกย่อหน้าด้วยบรรทัดว่าง"><?= e($row['body']) ?></textarea><small>รองรับหัวข้อ ตัวหนา ตัวเอียง รายการ และลิงก์ผ่านเครื่องมือด้านบน แนบภาพในส่วนรูปประกอบ</small></div><label>แท็ก (คั่นด้วยเครื่องหมายจุลภาค)<input name="tags" value="<?= e($row['tags']) ?>" maxlength="500"></label></section>
<?php if($type==='event'): ?><section class="admin-panel form-panel"><h2>ข้อมูลกิจกรรม</h2><div class="form-grid"><label>เริ่มกิจกรรม<input type="datetime-local" name="starts_at" value="<?= e($dateValue($row['starts_at'])) ?>"></label><label>สิ้นสุดกิจกรรม<input type="datetime-local" name="ends_at" value="<?= e($dateValue($row['ends_at'])) ?>"></label></div><label>สถานที่<input name="location" value="<?= e($row['location']) ?>" maxlength="500"></label><label>สถานะกิจกรรม<select name="event_status"><option value="normal">ปกติ</option><option value="cancelled" <?= $row['event_status']==='cancelled'?'selected':'' ?>>ยกเลิก</option></select></label></section><?php endif ?>
<?php if(in_array($type,['event','video','banner'],true)): ?><section class="admin-panel form-panel"><label>ลิงก์ภายนอก (http/https)<input type="url" name="external_url" value="<?= e($row['external_url']) ?>"><small><?= $type==='video'?'วิดีโอเปิดที่เว็บไซต์ต้นทาง':'ลิงก์ข้อมูลเพิ่มเติมหรือปลายทาง' ?></small></label></section><?php endif ?>
<section class="admin-panel form-panel"><div class="panel-heading"><h2><?= $type==='album'?'ภาพในอัลบั้ม':'รูปประกอบและไฟล์แนบ' ?></h2><a class="text-link" href="/admin/media" target="_blank" rel="noopener">อัปโหลดไฟล์ ↗</a></div><p class="form-note">แนบไฟล์ได้สูงสุด 1,000 รายการ เลือกรายการจากคลังสื่อ ลำดับแสดงตามลำดับที่เลือกบันทึก</p><div class="media-selection" data-media-selection><label>เลือกโฟลเดอร์ของงาน<select data-media-folder><option value="all">ทุกโฟลเดอร์</option><option value="0">ยังไม่จัดโฟลเดอร์</option><?php foreach($folders as $mediaFolder): ?><option value="<?= (int)$mediaFolder['id'] ?>"><?= e($mediaFolder['name']) ?></option><?php endforeach ?></select></label><?php if($media): ?><div class="button-row media-selection-actions" hidden><button type="button" class="button secondary" data-select-media="all">เลือก<?= $type==='album'?'ภาพ':'ไฟล์' ?>ทั้งหมด</button><button type="button" class="button secondary" data-select-media="none">ยกเลิกการเลือกทั้งหมด</button><span class="form-note" data-selection-count role="status" aria-live="polite"></span></div><?php endif ?><div class="media-picker"><?php foreach($media as $file): ?><label class="media-option" data-folder="<?= (int)$file['folder_id'] ?>"><input type="checkbox" name="media_ids[]" value="<?= $file['id'] ?>" <?= in_array((int)$file['id'],array_map('intval',$selected),true)?'checked':'' ?>><?php if(str_starts_with($file['mime'],'image/')): ?><img src="/files/<?= $file['id'] ?>" alt="<?= e($file['alt']) ?>" loading="lazy"><?php else: ?><?= icon('news',30) ?><?php endif ?><span><?= e($file['name']) ?></span></label><?php endforeach ?></div></div><?php if(!$media): ?><p class="muted">อัปโหลดไฟล์ผ่านคลังสื่อก่อนเลือกไฟล์แนบ</p><?php endif ?></section></div>
<aside><section class="admin-panel form-panel"><h2>การเผยแพร่</h2><label>สถานะ<select name="status"><?php foreach(STATUSES as $key=>$label): if($key==='trash'||($u['role']==='author'&&$key!=='draft'))continue; ?><option value="<?= $key ?>" <?= $row['status']===$key?'selected':'' ?>><?= $label ?></option><?php endforeach ?></select></label><label>วันเวลาเผยแพร่<input type="datetime-local" name="published_at" value="<?= e($dateValue($row['published_at'])) ?>"><small>เวลาประเทศไทย · เว้นว่างเมื่อเผยแพร่ทันที</small></label><label>หมวดหมู่<select name="category_id"><option value="">เลือกหมวดหมู่</option><?php foreach($categories as $cat): ?><option value="<?= $cat['id'] ?>" <?= (int)$row['category_id']===(int)$cat['id']?'selected':'' ?>><?= e($cat['name']) ?></option><?php endforeach ?></select></label><label>โฟลเดอร์รูปปก<select data-cover-folder><option value="all">ทุกโฟลเดอร์</option><option value="0">ยังไม่จัดโฟลเดอร์</option><?php foreach($folders as $mediaFolder): ?><option value="<?= (int)$mediaFolder['id'] ?>"><?= e($mediaFolder['name']) ?></option><?php endforeach ?></select><small>ใช้โฟลเดอร์เดียวกับภาพของงาน</small></label><label>รูปปก<select name="cover_id"><option value="">ไม่มีรูปปก</option><?php foreach($media as $file): if(!str_starts_with($file['mime'],'image/'))continue; ?><option data-folder="<?= (int)$file['folder_id'] ?>" value="<?= $file['id'] ?>" <?= (int)$row['cover_id']===(int)$file['id']?'selected':'' ?>><?= e($file['name']) ?></option><?php endforeach ?></select></label><img class="cover-preview" data-cover-preview src="<?= $row['cover_id']?'/files/'.(int)$row['cover_id']:'/assets/person.svg' ?>" alt="ภาพปก" <?= !$row['cover_id']?'hidden':'' ?>><p class="form-note" data-cover-folder-note hidden></p><label>URL<input name="slug" value="<?= e($row['slug']) ?>" maxlength="160"><small>เว้นว่างเพื่อสร้างจากชื่อเรื่อง หากซ้ำจะเติมเลขท้ายอัตโนมัติ</small></label></section><section class="admin-panel form-panel"><h2>ผลการค้นหาและแชร์</h2><label>ชื่อสำห